const captions = $('GPT-4: Generate Captions').first().json.message?.content || '';
const imageUrl  = $('DALL-E 3: Generate Product Image').first().json.data?.[0]?.url || 'N/A';

const week = new Date().toLocaleDateString('cs-CZ', { week: 'short', year: 'numeric' });

return [{ json: {
  week,
  captions,
  imageUrl,
  summary: `Obsah pro tyden ${week} vygenerovan. Captions: ${captions.length} znaku. Obrazek: ${imageUrl !== 'N/A' ? 'OK' : 'CHYBA'}`
}}];
